const raw = $input.first().json.output ?? $input.first().json.text ?? '';
let rota = 'APP_USO';
let intencao = '';
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  rota = parsed.rota ?? 'APP_USO';
  intencao = parsed.intencao_resumida ?? '';
} catch(e) {
  rota = 'APP_USO';
}
const chatInput = $('Chat Trigger').item.json.chatInput ?? '';
return [{ json: { rota, intencao, chatInput } }];
